+bool IsTrendAligned(int dir, int idx, const double &emaData[], const double &closeData[])
+{
+   if(!InpUseEMATrendFilter) return true;
+   if(ArraySize(emaData) <= idx || emaData[idx] == 0.0) return true;
+   if(dir == 1 && closeData[idx] < emaData[idx]) return false; // Bloqueia compra abaixo da EMA 200
+   if(dir == -1 && closeData[idx] > emaData[idx]) return false; // Bloqueia venda acima da EMA 200
+   return true;
+}
+
+bool IsMarketTrending(int idx, const double &adxData[])
+{
+   if(!InpUseADXFilter) return true;
+   if(ArraySize(adxData) <= idx || adxData[idx] == 0.0) return true;
+   return (adxData[idx] >= InpMinADXLevel);
+}
+
+bool HasBullishRejection(double openP, double highP, double lowP, double closeP)
+{
+   if(!InpRequireRejectionCandle) return true;
+   bool isGreen = (closeP >= openP);
+   double totalRange = highP - lowP;
+   if(totalRange <= 0.0) return isGreen;
+   double lowerWick = MathMin(openP, closeP) - lowP;
+   return (isGreen || (lowerWick / totalRange >= 0.35));
+}
+
+bool HasBearishRejection(double openP, double highP, double lowP, double closeP)
+{
+   if(!InpRequireRejectionCandle) return true;
+   bool isRed = (closeP <= openP);
+   double totalRange = highP - lowP;
+   if(totalRange <= 0.0) return isRed;
+   double upperWick = highP - MathMax(openP, closeP);
+   return (isRed || (upperWick / totalRange >= 0.35));
+}
