}

bool IsRejectionCandle(int dir, const MqlRates &c)
{
   double totalRange = c.high - c.low;
   if(totalRange <= 0.0) return false;
   if(dir == 1) // Alta: pavio inferior de rejeição ou candle verde
   {
      double lowerWick = MathMin(c.open, c.close) - c.low;
      bool hasWickRej = (lowerWick / totalRange) >= 0.25;
      bool isBullishBody = (c.close > c.open);
