   int extraGap = 0;
   if(lineIndex >= 2) extraGap += 2; // gap antes do Suporte/Resistência
   if(lineIndex >= 4) extraGap += 2; // gap antes das Estruturas
   if(lineIndex >= 6) extraGap += 3; // gap antes do Flutuante/Status
   return g_lineYStart + (lineIndex * g_lineH) + extraGap;
}

