"bool IsRejectionCandle(int dir, const MqlRates &c)
{
   if(!InpRequireRejectionCandle) return true;
   double totalRange = c.high - c.low;
   if(dir == 1) // Alta: pavio inferior de rejeição (>= 35%) ou candle verde/doji
   {
      bool isGreen = (c.close >= c.open);
      if(totalRange <= 0.0) return isGreen;
      double lowerWick = MathMin(c.open, c.close) - c.low;
      return (isGreen || (lowerWick / totalRange >= 0.35));
   }
   else // Baixa: pavio superior de rejeição (>= 35%) ou candle vermelho/doji
   {
      bool isRed = (c.close <= c.open);
      if(totalRange <= 0.0) return isRed;
      double upperWick = c.high - MathMax(c.open, c.close);
      return (isRed || (upperWick / totalRange >= 0.35));
   }
