str_func = """string ExtractJsonString(string json, string key)
{
   int pos = StringFind(json, key);
   if(pos < 0) return "";
   pos += StringLen(key);
   if(StringGetCharacter(json, pos) == '"') pos++;
   int endPos = StringFind(json, "\\\"", pos);
   if(endPos < 0) return "";
   return StringSubstr(json, pos, endPos - pos);
}

"""

# 1. Update build_ea()
